import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="قرارات أكاديمية متفرقة"
save("0238",N,[
("rule",[1],"قرارات متفرقة (خدمة القبول الإلكتروني الموحد)","وافق مجلس التعليم العالي على مشروع خدمة القبول الإلكتروني الموحد للجامعات الرسمية، حيث ستقوم شركة مايكروسوفت بتغطية نفقات المشروع البالغة 450,000 دولار أمريكي، وتخصص تكلفة الأجهزة التشغيلية للمشروع البالغة 100,000 دينار أردني على الجامعات حسب عدد الطلبة المقبولين في كل جامعة عن طريق القبول الموحد.",
 "من يغطي نفقات مشروع خدمة القبول الإلكتروني الموحد للجامعات الرسمية؟","كم تبلغ تكلفة مشروع القبول الإلكتروني الموحد وكيف توزع تكلفة الأجهزة على الجامعات؟","مين بدفع تكاليف مشروع القبول الموحد الإلكتروني؟"),
("rule",[1],"قرار مجلس العمداء (الكتب المقررة باللغة الإنجليزية)","أكد مجلس العمداء على ضرورة التدريس في المساقات العلمية باللغة الإنجليزية، وعلى عدم اعتماد أي كتاب مقرر من قبل مدرس المساق ما لم يكن قد قيّم واعتمد من لجنة البحث العلمي في الجامعة. ويرجى من أعضاء هيئة التدريس اعتماد كتب مقررة باللغة الإنجليزية للمساقات التي يدرسونها سواء كانت من تأليفهم أو من تأليف غيرهم، على أن يعرض الكتاب للتقييم من قبل عميد البحث العلمي قبل اعتماده كمقرر للتدريس.",
 "هل يجوز لمدرس المساق اعتماد كتاب مقرر دون تقييم من لجنة البحث العلمي؟","بأي لغة تدرس المساقات العلمية حسب قرار مجلس العمداء وما شرط اعتماد الكتب؟","بقدر اعتمد كتاب من تأليفي كمقرر؟"),
("rule",[1],"قرار مجلس العمداء (مدرسو متطلبات الحاسوب والإنجليزية)","يجوز تدريس متطلبات الجامعة من مساقات الحاسوب واللغة الإنجليزية من قبل مدرسين يحملون درجة الماجستير شريطة ألا يكونوا من المتخصصين ممن لا تقل خبرتهم التدريسية عن سنتين، ولا يحسب هؤلاء المدرسون إلى مجموع أعضاء الهيئة التدريسية المعمول بها في معايير الاعتماد أو في معايير الاعتماد الخاص، ولا يعتمد ذلك لأغراض تحديد الطاقة الاستيعابية.",
 "هل يجوز أن يدرس حملة الماجستير مساقات الحاسوب واللغة الإنجليزية في متطلبات الجامعة؟","هل يحسب مدرسو الماجستير لمتطلبات الجامعة ضمن نسبة أعضاء هيئة التدريس في الاعتماد؟","مين بقدر يدرس مساقات الحاسوب والإنجليزي بمتطلبات الجامعة؟"),
("rule",[1],"قرار مجلس الاعتماد (2001/4/17) تعديل","وفق تعديل قرار مجلس الاعتماد، يجوز تدريس متطلبات الجامعة من مساقات الحاسوب ومهارات اللغة الإنجليزية من قبل مدرسين متخصصين يحملون درجة الماجستير. ويمكن لمدرسي هذه المساقات أن يوظفوا في الأقسام المناسبة على ألا يحسب منهم أكثر من نسبة معينة من مجموع أعضاء هيئة التدريس. وعند احتساب الطاقة الاستيعابية لأي تخصص أكاديمي يدخل فقط المدرسون المختصون ممن تقع تخصصاتهم ضمن مجالات التخصص. ويعمم القرار على الجامعات الرسمية والخاصة ويعمل به اعتباراً من تاريخه.",
 "على من يعمم قرار مجلس الاعتماد المتعلق بمدرسي مساقات الحاسوب واللغة الإنجليزية؟","كيف تحتسب الطاقة الاستيعابية لتخصص أكاديمي بالنسبة لمدرسي الماجستير؟","القرار اللي بخص مدرسي الماجستير لمساقات الحاسوب بينطبق على الجامعات الخاصة؟"),
("rule",[1],"قرار مجلس العمداء (جداول المحاضرات والشعب، أولاً)","يؤكد مجلس العمداء على الالتزام بمواعيد المحاضرات والشعب التي تظهر في جريدة المواد ولا يجوز إجراء أي تعديل إلا بموافقة الأستاذ نائب الرئيس أو رئيس لجنة الجدول الدراسي، وذلك لما يسببه من إشكالات للطلبة أثناء فترة التسجيل، مثل صعوبة معرفة الأوقات الجديدة ووصولها للطلبة، والتعارض ما بين أوقات الجداول المعلنة والأوقات الجديدة التي عدلت مما يؤدي إلى تعارض لدى تسجيل الطلبة، وزيادة كبيرة في أعداد الطلبة الذين يضطرون لإجراء عملية السحب والإضافة نتيجة التعديلات.",
 "هل يجوز للمدرس تعديل موعد المحاضرة أو الشعبة بعد ظهورها في جريدة المواد؟","من يوافق على تعديل مواعيد المحاضرات والشعب بعد إعلانها؟","بدي أغير موعد محاضرتي، مين لازم يوافق؟"),
("rule",[2],"قرار مجلس العمداء (الإرشاد والسحب والإضافة، ثانياً-رابعاً)","على المرشدين معرفة وقراءة إجراءات التسجيل والتقيد بها بما يساعد في التقليل من عمليات الانسحاب والإضافة. ويسمح بقرار من مجلس العمداء بالسحب والإضافة في الحالات التالية: إذا تم تغيير تخصص الطالب، وإذا توقف تخرج الطالب لحين إنهاء مساق، وإذا ألغي مساق مما كان مسجلاً فيه الطالب ورغب في التسجيل لمساق آخر، وإذا لم يكن قد أتم المتطلب السابق، وفي حالة الإضافة فقط. ولا يجوز إرشاد الطلبة للتسجيل لمساق إذا لم يدرس المتطلب السابق له.",
 "ما الحالات التي يسمح فيها بالسحب والإضافة بقرار من مجلس العمداء؟","هل يجوز إرشاد الطالب للتسجيل لمساق لم يدرس متطلبه السابق؟","في أي حالات بقدر أسحب وأضيف بعد المدة؟"),
("rule",[2],"قرار مجلس العمداء (الجدول الدراسي، 1-8)","على رؤساء الأقسام مراعاة الأمور التالية عند إعداد الجدول الدراسي: أن تكون المساقات والشعب المطروحة في كل قسم تلبي رغبات الطلبة من حيث العدد المقرر لكل مساق/شعبة؛ وأن تكون المحاضرات موزعة على أيام الأسبوع؛ وألا تمتد المحاضرات إلى الساعة الثالثة للمساقات النظرية؛ ولا يجوز إجراء تغيير على الجدول بعد اعتماده ونشره على الإنترنت؛ وفي حالة وجود شعب متعددة للمساق يجب ألا يكون تزامن بين عدد من تلك الشعب؛ وأن يكون طرح المساقات حسب الخطط الاسترشادية للطلبة بحيث يتم طرح جميع المساقات الموجودة في الخطة الاسترشادية للفصل الأول لكل سنة؛ والتنسيق بين العمداء ورؤساء الأقسام بخصوص القاعات بحيث يتم استغلالها بالشكل الأمثل؛ ومراعاة الأعداد المقرر قبولها في العام التالي.",
 "ما الأمور التي يجب أن يراعيها رؤساء الأقسام عند إعداد الجدول الدراسي؟","هل يجوز تغيير الجدول الدراسي بعد اعتماده ونشره على الإنترنت؟","شو القواعد لما القسم بيعمل الجدول الدراسي؟"),
("rule",[2],"قرار مجلس العمداء (الالتزام بالقاعات والجداول)","يرجى من أعضاء الهيئة التدريسية الالتزام التام بمواعيد المحاضرات والشعب والقاعات التدريسية المحددة في الجدول الدراسي والمطروحة في الجدول الدراسي، وعدم تغييرها إلا بعد التنسيق مع وحدة القبول والتسجيل خطياً، وذلك لتلافي الإشكاليات التي قد تحدث أثناء الامتحانات الفصلية.",
 "هل يجوز لعضو هيئة التدريس تغيير القاعة أو موعد المحاضرة دون تنسيق؟","مع من يجب التنسيق لتغيير القاعات والمواعيد؟","بدي أغير قاعة محاضرتي، شو الإجراء؟"),
("rule",[2],"قرار تنظيم الامتحانات المحوسبة (1-4)","بهدف تنظيم عملية عقد الامتحانات بواسطة الحاسوب وضمان نجاح العملية يجب: إبلاغ كلية تكنولوجيا الحاسوب والمعلومات ومركز تكنولوجيا المعلومات والاتصالات في الجامعة بجداول الامتحانات ومواعيدها قبل فترة كافية (لا تقل عن شهر) بما فيها أعداد الطلبة وأسماؤهم ومواعيد امتحاناتهم والمدة المحددة للامتحان؛ وتوفير مشرف مختبر من الكلية للمساعدة في الإشراف على الامتحانات؛ وضرورة إعداد الأسئلة وتجربتها قبل المباشرة باستخدامها مع مراجعة المواد والأسئلة والإجابات للتأكد من عدم وجود أحرف أو رموز أو معلومات غير صحيحة قد لا تساعد الطالب على فهم السؤال؛ وتقوم كلية تكنولوجيا الحاسوب والمعلومات بوضع البرنامج الذي يسمح بتغيير الإجابة أو حذف الأسئلة التي لها Low Difficulty Index أو Negative Discrimination Index لعمل تحليل فوري عند انتهاء الامتحان.",
 "ما متطلبات تنظيم عقد الامتحانات بواسطة الحاسوب في الجامعة؟","قبل كم من الوقت يجب إبلاغ كلية الحاسوب ومركز تكنولوجيا المعلومات بجداول الامتحانات المحوسبة؟","شو لازم أعمل قبل ما أعقد امتحان محوسب؟"),
("rule",[2],"قرار مجلس العمداء (ع103 وL ز099، 2005/2006)","وافق مجلس العمداء على إجراء امتحان فصلي واحد خلال الفصل الدراسي لمساقي (ع103) «مختبر لغة عربية» و(ل ز099) «مختبر لغة إنجليزية»، ويطبق ذلك اعتباراً من بدء العام الجامعي 2005/2006.",
 "كم امتحاناً فصلياً يعقد لمساقي مختبر لغة عربية ومختبر لغة إنجليزية؟","من أي عام يطبق إجراء امتحان فصلي واحد في ع103 ول ز099؟","كم اختبار فصلي بمختبر اللغة العربية؟"),
("rule",[2],"قرارات مجلس العمداء (الإسعاف والطوارئ، النظم الحيوية، التربية الوطنية)","وافق المجلس على استحداث برنامج البكالوريوس في الإسعاف والطوارئ في كلية العلوم الطبية التطبيقية اعتباراً من بداية العام 2007/2008، وعلى تجميد القبول في قسم هندسة النظم الحيوية بكلية الهندسة اعتباراً من العام الجامعي 2006/2007 مع استمرار القسم بأداء خدمته حتى تخريج الطلبة الدارسين فيه. ووافق على تخصيص فصل إضافي في مساق التربية الوطنية يتضمن معلومات عن الأسرة الوطنية واستراتيجيات العمل المتعلقة بها وبالطفولة والمرأة وبالمهارات والأدوار الأساسية لأفراد الأسرة.",
 "ما البرنامج الذي استحدث في كلية العلوم الطبية التطبيقية عام 2007/2008؟","هل جمد القبول في قسم هندسة النظم الحيوية وهل يستمر القسم بخدمة طلبته؟","شو الموضوع الإضافي اللي أضيف لمساق التربية الوطنية؟"),
("rule",[3],"قرار مجلس العمداء (مساق التربية الوطنية، ورشة آل البيت)","وافق المجلس على محاور مساق التربية الوطنية الواردة في توصيات الورشة المتعلقة بمساق التربية الوطنية التي عقدت في رحاب جامعة آل البيت عطفاً على الورشة التي أقيمت في رحاب جامعة اليرموك، وعلى ترك الآلية تدريس مساق التربية الوطنية للجامعات الأردنية وذلك بالتنسيق فيما بينها للاستفادة من إمكانية تدريسها عن طريق شبكة الإنترنت.",
 "ما قرار مجلس العمداء بخصوص محاور مساق التربية الوطنية؟","هل يمكن تدريس مساق التربية الوطنية عن طريق الإنترنت بالتنسيق بين الجامعات؟","شو آلية تدريس التربية الوطنية حسب التوصيات؟"),
("rule",[3],"قرار مجلس العمداء (معادلة ل ز99 وL ز111)","قرر مجلس العمداء عدم الموافقة على معادلة مساقي (ل ز99) و(ل ز111) للطلبة الذين يتقدمون لامتحان المستوى في هذين المساقين ويخفقون ثم يتقدمون بطلب المعادلة.",
 "هل تعادل مساقات ل ز99 وl ز111 لمن أخفق في امتحان المستوى؟","ماذا يحدث لطلب معادلة ل ز99 وl ز111 المقدم بعد الإخفاق في امتحان المستوى؟","رسبت بامتحان المستوى وبدي أعادل ل ز99، بنوافق؟"),
("rule",[3],"قرار مجلس العمداء (اعتماد علامات الامتحان النهائي تلقائياً)","وافق مجلس العمداء على اعتماد علامات الطلبة في الامتحان النهائي التي لم يتم اعتماد نتائجها ضمن المدة المحددة وهي 72 ساعة من تاريخ عقد الامتحان النهائي للمساق، تلقائياً من قبل الحاسوب.",
 "ماذا يحدث لعلامات الامتحان النهائي التي لم تعتمد خلال 72 ساعة؟","من يعتمد علامات الطلبة تلقائياً بعد انتهاء مدة 72 ساعة؟","إذا المدرس ما اعتمد العلامات، شو بيصير؟"),
("rule",[3],"قرار مجلس العمداء (الإنذارات والتنسيق بين الجامعات)","أقر المجلس إظهار الإنذارات في كشوف العلامات العائدة للطلبة المشاغبين (ظاهرة العنف فقط) مع إعطائهم فرصة لإلغاء هذا الإنذار، والتنسيق بين الجامعات للتقيد بعدم قبول أي طالب مفصول بسبب ظاهرة العنف الطلابي في أي جامعة أردنية ولمدة عام على الأقل.",
 "هل تظهر الإنذارات على كشف علامات الطلبة المشاغبين وهل يمكن إلغاؤها؟","هل يقبل الطالب المفصول بسبب العنف الطلابي في جامعة أردنية أخرى؟","فصلت بسبب مشاجرة، بقدر أنقبل بجامعة ثانية؟"),
("rule",[3],"كتاب (دفع رسوم الموازي من خارج الأردن)","يمكن للطلبة المقبولين في البرنامج الموازي من خارج الأردن دفع الرسوم الجامعية بحوالة مالية على حساب الجامعة لدى البنك العربي (فرع إربد)، بحيث يتم تحويل المبلغ بالدينار الأردني أو ما يعادله، وتسوية العمولة النهائية لأي فروقات لاحقاً.",
 "كيف يدفع الطالب المقبول في الموازي من خارج الأردن رسومه الجامعية؟","بأي عملة تحول رسوم الموازي من خارج الأردن؟","أنا خارج الأردن ومقبول موازي، كيف بدفع الرسوم؟"),
("rule",[3],"قرار مجلس التعليم العالي (فحص الإيدز)","ألزم مجلس التعليم العالي الجامعات وكليات المجتمع بتغطية نفقات فحص الإيدز للطلبة الجدد الملتحقين لديهم.",
 "من يتحمل نفقات فحص الإيدز للطلبة الجدد؟","هل تلزم الجامعات بتغطية فحص الإيدز للطلبة المستجدين؟","هل أدفع أنا فحص الإيدز عند التسجيل؟"),
("rule",[3],"قرار مجلس العمداء (جلسات مناقشة التخرج)","حدد المجلس ثلاث جلسات رئيسية لمناقشة تخريج الطلبة، يقدم خلالها عميد الكلية تنسيبات مجلس كليته بتخريج طلبته، ويقدم للمجلس دراسة إحصائية تشمل عدد الخريجين وتوزيع تقديراتهم، وتكون مواعيد الجلسات مع نهاية الفصل الأول والثاني والصيفي، وتحدد موعد الجلسة قبل أسبوع من تسليم العلامات النهائية لوحدة القبول والتسجيل. وتناقش تنسيبات الكلية الخاصة بطلبات التخريج المتأخرة في أول جلسة للمجلس تعقد في بداية كل شهر.",
 "كم جلسة رئيسية لمناقشة تخريج الطلبة يعقدها مجلس العمداء ومتى؟","متى تناقش طلبات التخريج المتأخرة؟","متى بتتناقش أسماء الخريجين بمجلس العمداء؟"),
("rule",[3],"قرار مجلس التعليم العالي (انتقال طلبة الجامعة العربية المفتوحة)","وافق المجلس على السماح لطلبة البكالوريوس في الجامعة العربية المفتوحة بالانتقال إلى الجامعات الأردنية بشروط: أن يكون البرنامج المنتقل منه معتمداً اعتماداً خاصاً، وأن لا يقل معدله في الثانوية العامة عن الحد الأدنى للقبول في الجامعات الأردنية الرسمية للتخصص الراغب بالانتقال إليه، وتحقيق شروط الانتقال التي تطلبها الجامعة المنتقل إليها. ويترك للجامعات الأردنية قبول خريجي الجامعة العربية المفتوحة في برامج الدراسات العليا بشرط أن يكون البرنامج معتمداً اعتماداً خاصاً، وأن يجتاز الطالب امتحان الكفاءة بنتيجة تزيد عن المعدل الوطني في التخصص الراغب بالالتحاق به، وأن يحقق الشروط الأخرى المتعلقة بالدراسات العليا التي أقرها مجلس التعليم العالي.",
 "ما شروط انتقال طلبة الجامعة العربية المفتوحة إلى الجامعات الأردنية؟","ما شروط قبول خريجي الجامعة العربية المفتوحة في الدراسات العليا؟","أنا بالجامعة العربية المفتوحة وبدي أنتقل لجست، شو الشروط؟"),
("rule",[3],"قرار مجلس التعليم العالي (الأكاديمية العربية للعلوم المالية والمصرفية)","وافق مجلس التعليم العالي على احتساب ساعات معتمدة للطلبة المنتقلين من الأكاديمية العربية للعلوم المالية والمصرفية إلى الجامعات الأردنية بما يتناسب مع الخطط الدراسية المعمول بها في كل جامعة وفي تخصصات البكالوريوس التالية الواردة في قرار المجلس رقم 924 تاريخ 2005/1/6 فقط: التسويق، ونظم المعلومات الإدارية والمالية، وإدارة الأعمال، وعدم الموافقة على احتساب أي ساعة في أي تخصص آخر.",
 "في أي تخصصات تحتسب ساعات الطلبة المنتقلين من الأكاديمية العربية للعلوم المالية والمصرفية؟","هل تحتسب ساعات المنتقل من الأكاديمية العربية المالية في تخصص الهندسة؟","انتقلت من الأكاديمية المالية والمصرفية، أي تخصصات بتنحسب لي ساعاتها؟"),
("rule",[4],"قرارات مجلس التعليم العالي (جامعة القدس المفتوحة، المبعوثون)","وافق مجلس التعليم العالي على عدم احتساب الساعات التي ينهيها الطالب في جامعة القدس المفتوحة في حال رغبته بالانتقال إلى إحدى الجامعات الأردنية. وعدم منح الشهادة الجامعية (المصدقة) للطلبة المبعوثين على نفقة مؤسسة الضمان الاجتماعي إلا بعد حصول الطالب على كتاب براءة ذمة من المؤسسة. ويرجى عدم السماح لأي طالب مبعوث من مديرية الأمن العام بالتحويل إلى تخصص آخر إلا بعد أخذ موافقتها أولاً.",
 "هل تحتسب الساعات التي أنهاها الطالب في جامعة القدس المفتوحة عند الانتقال لجامعة أردنية؟","متى تمنح المصدقة الجامعية للمبعوثين على نفقة مؤسسة الضمان الاجتماعي؟","مبعوث من الأمن العام وبدي أغير تخصصي، شو أعمل؟"),
("rule",[4],"قرار مجلس التعليم العالي (المبعوثون على نفقة المجلس)","لا يسمح للطلبة المبعوثين على نفقة مجلس التعليم العالي (الوافدين) بسحب المساقات الفصلية المسجلة بعد انتهاء فترة السحب والإضافة المقررة في الجامعة أو قبل الامتحانات النهائية لما يترتب على ذلك من تحمل المجلس للرسوم الدراسية، ولا يسمح لهم بالتأجيل لأي فصل إلا بعد الحصول على موافقة خطية من المكتب الثقافي.",
 "هل يسمح للمبعوثين على نفقة مجلس التعليم العالي بسحب المساقات بعد فترة السحب والإضافة؟","متى يسمح بتأجيل الدراسة للطالب المبعوث على نفقة مجلس التعليم العالي؟","أنا مبعوث، بقدر أأجل فصل؟"),
("rule",[4],"كتب وزارة التعليم العالي (الطلبة السوريون والعمانيون)","على جميع الطلبة السوريين الموفدين الذين يدرسون ضمن التبادل الثقافي الأردني السوري الدراسة فقط بموافقة سفارتهم وباسم الشهادة التي سيحصلون عليها في نهاية دراستهم. وأرفق كتاب المستشار الثقافي الأردني/مسقط المتضمن طلبه توعية الطلبة العمانيين في الجامعات الأردنية بضرورة تصديق شهاداتهم ووثائقهم الصادرة عن جامعاتهم من وزارة التعليم العالي ووزارة الخارجية الأردنية.",
 "ما الذي يجب على الطلبة العمانيين فعله لتصديق شهاداتهم من الجامعات الأردنية؟","ما شرط دراسة الطلبة السوريين الموفدين ضمن التبادل الثقافي؟","طالب عماني، كيف بصدق شهادتي؟"),
("rule",[4],"كتب وزارة التعليم العالي ووزارة التربية (المبعوثون وأبناء المعلمين)","لا مانع لدى وزارة التعليم العالي من تسليم الطلبة الخريجين المبعوثين على نفقتها كافة وثائق التخرج. ولا مانع لدى وزارة التربية والتعليم من انتقال الطلبة المقبولين على حساب المكرمة الملكية السامية لأبناء المعلمين من جامعة إلى أخرى أو من تخصص إلى آخر ضمن الأسس والشروط التي تعتمدها الجامعات لهذه الغاية. ولا يسمح للطلبة الموفدين على نفقة وزارة التربية والتعليم بتغيير التخصص أو الجامعة الموفد إليها دون الحصول على الموافقة المسبقة من لجنة البعثات المركزية.",
 "هل يسمح لأبناء المعلمين المقبولين بالمكرمة الملكية بالانتقال بين الجامعات والتخصصات؟","هل يسمح للموفدين على نفقة وزارة التربية والتعليم بتغيير التخصص بدون موافقة؟","أنا مبعوث من وزارة التربية، بقدر أغير تخصصي؟"),
("rule",[4],"قرار مجلس العمداء (احتفالات التخرج)","للحد من المظاهر السلبية والعشوائية لاحتفالات التخرج قرر مجلس العمداء: التنسيق مع عمادة شؤون الطلبة وكلية الدراسات العليا والأقسام المعنية لتحديد مكان عقد هذه الاحتفالات مسبقاً؛ وتحديد الفترة الزمنية لها بحيث تكون في النصف الثاني من شهر كانون الأول للفصل الدراسي الأول والنصف الأول من شهر أيار للفصل الدراسي الثاني على أن تنتهي قبل بداية الامتحانات النهائية؛ وتوفير الأجهزة اللازمة من خلال عمادة شؤون الطلبة وذلك لمنع استغلال الطلبة مادياً؛ وأخذ الموافقة قبل فترة زمنية كافية للترتيب والإعداد لهذه الاحتفالات وجدولتها تمهيداً لتعميمها على الأقسام.",
 "متى يسمح بعقد احتفالات التخرج للطلبة حسب قرار مجلس العمداء؟","ما الضوابط التي حددها مجلس العمداء للحد من المظاهر السلبية في احتفالات التخرج؟","متى بقدر أسوي احتفال تخرج مع زملائي؟"),
("rule",[4,5],"قرار مجلس الأمناء (أبناء العاملين في الموازي، 2005/2006)","يقبل أبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية في البرنامج الموازي اعتباراً من العام الجامعي 2005/2006 بشروط: أن يكون والد الطالب على رأس عمله أثناء قبول الطالب أو أن يكون قد أمضى في خدمة الجامعة عشر سنوات على الأقل أو أن يكون قد توفي وهو على رأس عمله، وألا يكون الطالب مبعوثاً من جهة رسمية أو غير رسمية، وأن يكون الطالب في مرحلة البكالوريوس. وتحدد الساعات المعتمدة لأبناء العاملين بنسبة 50% من الرسوم الجامعية المقررة في البرنامج الموازي، ولا يجوز تخفيض هذه النسبة لأي سبب من الأسباب، على أن لا تزيد نسبة المقبولين عن 5% من أعداد المقبولين تنافسياً في البرنامج الموازي، وذلك استناداً لأحكام المادة (6/ب/6) من القانون المؤقت رقم 42 لسنة 2001، قانون الجامعات الأردنية الرسمية.",
 "ما شروط قبول أبناء العاملين في الجامعة في البرنامج الموازي وكم نسبة خصم الرسوم؟","ما أقصى نسبة لأبناء العاملين المقبولين في الموازي من المقبولين تنافسياً؟","أبوي موظف بالجامعة، شو شروط الموازي لي؟"),
("rule",[5],"قرار مجلس العمداء (تجميد القبول في إدارة الخدمات الصحية)","أكد مجلس العمداء على تجميد القبول في برنامج البكالوريوس في إدارة الخدمات الصحية بكلية الطب، من بدء العام الجامعي 2010/2011.",
 "هل جمد القبول في برنامج إدارة الخدمات الصحية بكلية الطب؟","من أي عام جمد القبول في إدارة الخدمات الصحية؟","بقدر أسجل إدارة الخدمات الصحية بالطب؟"),
("rule",[5],"قرارات مجلس العمداء (قوات الدرك، المفصولون، الشهادة المتوسطة)","قرر المجلس عدم قبول أي طالب على دراسة المديرية العامة لقوات الدرك إلا بموافقة خطية من المديرية. وعدم قبول الطلبة المفصولين من أي جامعة أردنية بسبب قضايا العنف الطلابي طيلة فترة العقوبة كحد أدنى. ومعاملة الطلبة الحاصلين على الشهادة الجامعية المتوسطة من خارج الأردن (نظام السنتين والنصف) من حيث الساعات المحتسبة بما لا يزيد عن 30 ساعة حداً أعلى ووفق الشروط الواردة في أسس التجسير المعمول بها.",
 "كم ساعة تحتسب لحامل الشهادة الجامعية المتوسطة من خارج الأردن عند الالتحاق؟","هل يقبل الطالب على دراسة الدرك بدون موافقة المديرية؟","شو شروط قبول طالب الدرك؟"),
("rule",[5],"قرار مجلس الأمناء (أبناء العاملين، 2012/2013)","قرر مجلس الأمناء: عدم قبول الطلبة من أبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية وجامعة اليرموك الحاصلين على الثانوية العامة غير الأردنية في تخصصات الطب البشري وطب الأسنان في البرنامجين العادي والموازي (أبناء العاملين بنصف الرسوم) اعتباراً من بدء العام الجامعي 2012/2013؛ وقبول أبناء العاملين من جامعة اليرموك في البرنامج العادي بما يتفق مع أسس القبول والقرارات الخاصة بقبول أبناء العاملين في الجامعة؛ واستيفاء الرسوم من جميع الطلبة الذين يتم الموافقة لهم على تغيير تخصصاتهم للتخصص الجديد حسب البرنامج الذي يقبلون فيه بما في ذلك الرسوم الفصلية وأي رسوم أخرى.",
 "هل يقبل أبناء العاملين الحاصلون على ثانوية غير أردنية في الطب وطب الأسنان بنصف الرسوم؟","كيف تستوفى الرسوم من الطالب الذي وافقت له الجامعة على تغيير تخصصه؟","غيرت تخصصي، بدفع حسب رسوم التخصص الجديد؟"),
("rule",[5],"قرار مجلس العمداء (احتفالات التخرج بين الفصلين، شروط الانتقال للطب)","قرر مجلس العمداء إلغاء احتفالات التخرج ما بين الفصلين الأول والثاني ويقتصر الاحتفال على الحفل الرئيسي فقط في نهاية العام الدراسي، ويطبق اعتباراً من تاريخ صدوره. ووافق على العمل بالتعليمات القديمة والجديدة لشروط الانتقال من سنة إلى أخرى في تعليمات منح درجة البكالوريوس في الطب والجراحة للعام الجامعي 2013/2014 ولعام واحد فقط.",
 "هل تقام احتفالات التخرج بين الفصلين الأول والثاني؟","هل يعمل بتعليمات الانتقال القديمة والجديدة للطب والجراحة في 2013/2014؟","احتفال التخرج مرة وحدة بالسنة؟"),
("rule",[5],"قرار مجلس العمداء (وثائق التخرج)","وافق مجلس العمداء على إصدار وثائق التخرج (شهادة جدارية، مصدقة، كشف علامات) الخاصة بخريجي الجامعة من ذوي الجنسيات العربية باللغة العربية ومن ذوي الجنسيات غير العربية باللغة الإنجليزية، وجعل الوثائق باللغة العربية اختيارية لهم.",
 "بأي لغة تصدر وثائق التخرج للخريجين العرب وغير العرب؟","هل الوثائق بالعربية اختيارية لغير العرب؟","شهادتي جدارية بالعربي ولا إنجليزي؟"),
("rule",[6],"قرار مجلس العمداء (تغيير التخصص وتحديد الخطة، الغياب)","وافق مجلس العمداء على إعطاء الصلاحية لعميد الكلية المعني باختيار الخطة المناسبة للطالب في حال تغيير تخصصه ويطبق القرار اعتباراً من تاريخ صدوره. وقرر إلزام أعضاء هيئة التدريس بإدخال الحضور والغياب للطلبة بشكل دوري، ومنع إدخال حركة غياب لأي طالب مضى على محاضرته أكثر من 10 أيام، وإرسال رسالة إلكترونية للطالب الذي يصل حد الغياب له 15%. وفوض عميد الكلية بتعديل وعدد ونسبة الغياب للطلبة في حال وجود خطأ في احتساب الغيابات بناءً على كتاب خطي من مدرس المادة.",
 "هل يجوز لعضو هيئة التدريس إدخال غياب بعد مرور أكثر من 10 أيام على المحاضرة؟","متى ترسل رسالة إلكترونية للطالب بخصوص غيابه؟","من يعدل نسبة الغياب إذا حصل خطأ في احتسابها؟"),
("rule",[6],"قرار مجلس العمداء (تطبيق قرار 2016/891، الاستشاري)","طبق مجلس العمداء قراره رقم 2016/891 بخصوص تعديل عدد من المواد في التعليمات العامة لمنح درجة البكالوريوس وتعليمات منح درجة البكالوريوس في الطب والجراحة وطب الأسنان على الطلبة المفصولين بأثر رجعي وبموافقة اللجنة العليا للدراسات الموازي. ووافق على قبول الطلبة الدارسين في كليات الطب من خارج المملكة (برنامج خمس سنوات) والراغبين بالدراسة لسنة إضافية (التدريب السريري في مستشفى الملك المؤسس عبد الله الجامعي) على البرنامج الدولي كدراسة خاصة في الجامعة، ويطبق ذلك اعتباراً من العام الجامعي 2016/2017.",
 "هل يقبل طلبة الطب الدارسون خارج المملكة لسنة التدريب السريري في مستشفى الملك المؤسس عبد الله؟","من أي عام يطبق قبول طلبة الطب من خارج المملكة في سنة التدريب السريري على البرنامج الدولي؟","درست طب خمس سنين بالخارج، بقدر أعمل سنة تدريب سريري عندكم؟"),
("rule",[6],"قرار مجلس العمداء (إقفال الحساب الإلكتروني، التخريج الصيفي)","وافق مجلس العمداء على تكليف رئيس القسم بإدخال علامة غير مكتمل في حال إقفال الحساب الإلكتروني لعضو هيئة التدريس غير المتفرغ والذي انتهت خدمته بعد اعتماد العلامات النهائية من قبل وحدة القبول والتسجيل. ووافق على السماح للطلبة الذين بقي عليهم مساق التدريب على الفصل الصيفي بحضور حفل التخرج على الفصل الدراسي الثاني فقط بناءً على تنسيب من العميد المعني بشؤون الطلبة.",
 "من يدخل علامة «غير مكتمل» إذا أغلق الحساب الإلكتروني لعضو هيئة تدريس غير متفرغ انتهت خدمته؟","هل يسمح لمن بقي عليه مساق تدريب صيفي بحضور حفل التخرج؟","باقي عليّ تدريب بالصيفي، بقدر أحضر حفل التخرج؟"),
("rule",[6],"قرار مجلس العمداء (صلاحية العميد في الحضور والغياب)","منح مجلس العمداء عميد الكلية صلاحية تجاوز نسبة 20% في كل ما يتعلق بالحضور والغياب وفي حالات خاصة يقدرها عميد الكلية.",
 "من يملك صلاحية تجاوز نسبة الغياب 20% في الحالات الخاصة؟","هل لعميد الكلية صلاحية في موضوع نسبة الحضور والغياب؟","غبت أكثر من 20% بظرف خاص، بقدر العميد يسمحلي؟"),
("rule",[6],"قرار مجلس العمداء (معدل 2.1 والإرشاد، المساقات الاختيارية)","وافق مجلس العمداء على تحديد معدل (2.1 من 4) فأقل للطلبة الذين يخضعون للإرشاد الخاص حسب نظام الرموز الجديد، اعتباراً من تاريخ صدور القرار. ووافق على استثناء مساقات الجامعة الاختيارية من المساقات المتاحة كبديلة للطالب اعتباراً من بدء العام الجامعي 2017/2018.",
 "ما المعدل الذي يخضع الطالب عنده للإرشاد الخاص حسب نظام الرموز الجديد؟","هل تعتبر مساقات الجامعة الاختيارية بديلة للطالب بعد 2017/2018؟","معدلي 2.1، بخضع للإرشاد الخاص؟"),
("rule",[7],"قرار مجلس العمداء (حظر الأجهزة في قاعة الامتحان)","أكد مجلس العمداء على حظر إدخال الطلبة الأجهزة الخلوية وجميع وسائل الاتصال إلى قاعة الامتحان باستثناء الآلة الحاسبة، واعتبار إدخال أي نوع من الأجهزة المذكورة أعلاه محاولة غش، والتأكيد على أعضاء الهيئة التدريسية ومراقبي الامتحانات بالتشدد في تطبيق نظام الطلبة المتعلق بالغش.",
 "على من يؤكد مجلس العمداء التشدد في تطبيق نظام الغش بخصوص الأجهزة في قاعة الامتحان؟","هل يعتبر إدخال جهاز اتصال إلى قاعة الامتحان محاولة غش؟","معي موبايل بالامتحان وهو مغلق، بعتبر غش؟"),
("rule",[7],"قرارات مجلس العمداء (ABET وجدول السحب والإضافة)","وافق مجلس العمداء على اعتماد شهادة الاعتماد الدولي لهيئة الاعتماد الأمريكية للبرامج الهندسية والتكنولوجية (ABET) لقسم الهندسة الميكاترونية وقسم الهندسة النووية في كلية الهندسة حتى 2021/9/30. وأقر مجلس العمداء جدولاً بمواعيد عمليتي السحب والإضافة وتعديل الأسس الخاصة بعملية التسجيل، يبين وقت البداية والنهاية لكل من الطالب ورئيس القسم والعميد: فرئيس القسم يضيف فقط (إضافة فقط) بعد موعد التسجيل بيوم وحتى نهاية الأسبوع الأول، والعميد يملك صلاحية التعديل حتى موعد بناء جدول الامتحانات حيث يوقف التسجيل والسحب والإضافة وكافة التعديلات على الجدول الدراسي.",
 "ما الجهة التي يحق لها الإضافة فقط بعد موعد التسجيل بيوم وحتى نهاية الأسبوع الأول؟","متى يتم إيقاف التسجيل والسحب والإضافة وكافة التعديلات على الجدول الدراسي؟","مين بقدر يضيف مساق بعد ما ينتهي التسجيل؟"),
("rule",[7],"قرار مجلس العمداء (الامتحانات النهائية)","وافق مجلس العمداء على تعديل الأسس الخاصة ببناء برامج الامتحانات (جميع الدرجات) بخصوص مدة عقد الامتحانات النهائية للفصلين الأول والثاني والصيفي، بحيث يصبح الامتحان النهائي في الفصلين الأول والثاني لمدة أسبوعين وفي الفصل الصيفي لمدة أسبوع واحد، اعتباراً من تاريخ صدور القرار.",
 "كم أسبوعاً مدة الامتحانات النهائية في الفصلين الأول والثاني والصيفي؟","هل مدة الامتحانات النهائية للصيفي أسبوع أم أسبوعان؟","كم بتستمر فترة الامتحانات النهائية بالفصل الصيفي؟"),
("rule",[7],"قرارات مجلس العمداء (الاعتمادات الدولية)","وافق مجلس العمداء على اعتماد: شهادة الهيئة الأمريكية لتعليم الصيدلة (ACPE) لبرامج الصيدلة في كلية الصيدلة حتى 2020/6/30؛ وشهادة (ABET) لبرنامج البكالوريوس في هندسة الحاسوب حتى 2021/9/30؛ وشهادة الاعتماد الدولي البريطاني (ASIC) لبرامج البكالوريوس في كلية العلوم الطبية التطبيقية حتى 2021/12/17؛ وشهادة (ASIIN) الألمانية لبرنامج البكالوريوس في تخصص التقنيات الحيوية والهندسة الوراثية في كلية العلوم والآداب؛ وشهادة الاعتماد الأمريكي (ACEN) لبرامج البكالوريوس في كلية التمريض.",
 "ما هيئات الاعتماد الدولي التي اعتمد مجلس العمداء شهاداتها لبرامج الصيدلة والتمريض والعلوم الطبية التطبيقية؟","أي شهادة اعتماد تخص برنامج التقنيات الحيوية والهندسة الوراثية وبرنامج التمريض؟","شو الاعتمادات الدولية لكلية الصيدلة والتمريض؟"),
("rule",[7],"قرار مجلس العمداء (الفصل الدراسي الثاني 2019/2020، حساب العلامات)","عدل مجلس العمداء آلية تقييم واحتساب العلامات للفصل الدراسي الثاني من العام الجامعي 2019/2020: إذا تم عقد الامتحان الأول قبل تعليق الدوام في الجامعة يتم اعتماد 50% علامة للامتحان النهائي، وإذا لم يعقد الامتحان الأول قبل تعليق الدوام يتم اعتماد 60% علامة للامتحان النهائي، ويطبق القرار من تاريخ صدوره.",
 "كيف احتسبت علامة الامتحان النهائي في الفصل الثاني 2019/2020 إذا عقد الامتحان الأول قبل تعليق الدوام؟","كم نسبة الامتحان النهائي إذا لم يعقد الامتحان الأول قبل تعليق الدوام في 2019/2020؟","كيف اتحسبت العلامات بفصل كورونا الثاني؟"),
("rule",[7],"قرار مجلس العمداء (تعديل التقويم الجامعي 2019/2020)","عدل مجلس العمداء التقويم الجامعي للعام 2019/2020 بحيث يكون: آخر موعد لإدخال واعتماد الأعمال الفصلية هو يوم الخميس 2020/5/21، وتاريخ فترة الانسحاب من الفصل/تأجيل الدراسة/الانسحاب من الجامعة (لطلبة البكالوريوس) وانتهاء فترة الانسحاب من المساقات النظرية (دون ترصيد الرسوم الجامعية) هو 2020/5/20، وفترة الامتحانات للمساقات النظرية من يوم السبت 2020/5/30 ولغاية يوم الخميس 2020/6/18.",
 "ما موعد الامتحانات النظرية بعد تعديل التقويم الجامعي 2019/2020؟","ما آخر موعد لإدخال واعتماد الأعمال الفصلية في الفصل الثاني 2019/2020؟","متى بتبدأ وتنتهي الامتحانات النظرية بالتقويم المعدل لـ 2020؟"),
],"b",verified="image")
